const defaults = {length: 'normal', min: 800, max: 1400, style: 'daily', custom: ''};
const lengths = {short: [400, 700], normal: [800, 1400], long: [1600, 2400]};
const styles = {
  daily: ['现代日常', '用具体生活细节、自然口语对白与轻微幽默组织日常。关系从共同做事和即时回应中显露；保留人物差异、冲突和失落，不强行温情或治愈。'],
  novel: ['轻小说群像', '以清楚的动作、鲜明对白与人物反应形成节奏，可有符合人物口吻的自然吐槽；不堆砌夸张比喻，不把所有人写成同一种声音。'],
  plain: ['克制白描', '以准确、简洁的动作、对白及可观察细节推进场景，少作解释与评价，让具体变化和停顿承担表达。'],
  lyrical: ['细腻抒情', '通过环境、声音、动作节奏和留白呈现细腻氛围，语言清楚节制，不把普通小事强写成宏大情绪。'],
  mystery: ['悬疑写实', '重视可观察线索、行动因果与人物信息差，细节有依据，疑点来自已有事实；不为营造气氛硬造危险或暗中改写设定。'],
  custom: ['自定义文风', ''],
};
const thoughtTags = 'think|thinking|reasoning|analysis|ECoT|cot|draft|draft_notes|acg_think|lore_search|combat_driver|story_driver|dice_calculation|parallel_line_drive';
const noiseRules = [
  {key:'thought-blocks', label:'思考与草稿块', pattern:'<('+thoughtTags+')\\b[^>]*>[\\s\\S]*?(?:<\\/\\1\\s*>|$)', flags:'gi', replacement:'', raw:true},
  {key:'thought-fences', label:'思考与草稿代码块', pattern:'```(?:thinking|think|reasoning|analysis|cot|draft)\\b[^\\n]*\\r?\\n[\\s\\S]*?(?:```|$)', flags:'gi', replacement:'', raw:true},
  {key:'thought-heading', label:'思考过程前缀', pattern:'^\\s*(?:思考过程|推理过程|内部分析|analysis|thinking|reasoning)\\s*[:：][\\s\\S]*?(?=<content\\b|$)', flags:'i', replacement:'', raw:true},
  {key:'thought-closers', label:'残留思考闭合标签', pattern:'<\\/(?:'+thoughtTags+')\\s*>', flags:'gi', replacement:'', raw:true},
  {key:'transport-tail', label:'异常工具协议尾缀', pattern:'(<\\/(?:content|time)\\s*>\\s*)(?:```[^\\r\\n]*\\r?\\n)?(?:call\\s*:\\s*default_api\\s*:\\s*antitrunc_reply\\b|<\\|(?:im_end|eot_id|endoftext)\\|>|\\[DONE\\])[^]*$', flags:'gi', replacement:'$1', raw:true},
  {key:'partial-tag', label:'流式未完成标签', pattern:'<(?:[A-Za-z_/][^>\\r\\n]*)?$', flags:'g', replacement:'', raw:false},
];
function cleanOutput(raw, delimiters) {
  let text = String(raw ?? '');
  if (delimiters?.prefix && delimiters?.suffix) {
    const escape = value => String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    text = text.replace(new RegExp(escape(delimiters.prefix)+'[\\s\\S]*?(?:'+escape(delimiters.suffix)+'|$)','g'), '');
  }
  for (const rule of noiseRules) text = text.replace(new RegExp(rule.pattern, rule.flags), rule.replacement);
  return text;
}
function normalizeConfig(value) {
  const c = {...defaults, ...value};
  if (!Object.hasOwn(lengths, c.length) && c.length !== 'custom') throw Error('请选择有效的字数档位。');
  if (!Object.hasOwn(styles, c.style)) throw Error('请选择有效的文风。');
  if (c.length !== 'custom') [c.min, c.max] = lengths[c.length];
  c.min = Number(c.min); c.max = Number(c.max);
  if (!Number.isInteger(c.min) || !Number.isInteger(c.max) || c.min < 100 || c.max > 10000 || c.min > c.max) throw Error('自定义字数须为100—10000之间的整数，且下限不高于上限。');
  c.custom = String(c.custom ?? '').trim();
  if (c.style === 'custom' && !c.custom) throw Error('选择自定义文风时，请填写文风内容。');
  return c;
}
function writingPrompt(value) {
  const c = normalizeConfig(value);
  return '<xzs_writing_config>\n正文目标：' + c.min + '—' + c.max + '个可见字符，优先写到区间中段约' + Math.round((c.min+c.max)/2) + '字。只计叙述与对白；空白、标签、思考、时间戳、协议标记和媒体控件不计。中文、标点、字母及数字各计一个字符。收束前核对正文篇幅：低于' + c.min + '字时补足当前互动的具体动作、对白与可观察细节，不把约数当作可以提前结束的理由。字数是写作目标，不通过截断补齐；扩写当前互动，不为了篇幅替玩家决定或增加事件、镜头和经过时间。\n当前文风：' + styles[c.style][0] + '。\n' + (c.style === 'custom' ? c.custom : styles[c.style][1]) + '\n文风只控制语言、句式、节奏和描写密度，仍遵守人物、时间、知识边界、玩家控制及输出协议。\n</xzs_writing_config>';
}
function bodyText(raw) {
  let text = cleanOutput(raw);
  const blocks = [...text.matchAll(/<content\b[^>]*>([\s\S]*?)(?:<\/content\s*>|$)/gi)];
  if (!blocks.length) return null;
  text = blocks.map(m => m[1]).join('\n');
  return text.replace(/<(time|bbs_start|bbs_end|audio|video|script|style|iframe)\b[^>]*>[\s\S]*?(?:<\/\1\s*>|$)/gi, '')
    .replace(/^\s*[\[【](?:场景事件|剧情触发|世界事件|奉心祭)[\]】].*$/gm, '')
    .replace(/<!--[^]*?(?:-->|$)/g, '')
    .replace(/【(?:歌曲|演奏|演出|点歌|照片|场景|场景事件|事件|主线|剧情|XZS)[^】]*】/g, '')
    .replace(/\[\[(?:XZS|SCENE|STORY)[^\]]*\]\]/gi, '')
    .replace(/<[^>]*>/g, '')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/\*\*|__|~~|`/g, '')
    .replace(/&(?:amp|lt|gt|quot|apos|nbsp|#\d+|#x[\da-f]+);/gi, entity => {
      const named = {'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&apos;':"'",'&nbsp;':' '}[entity.toLowerCase()];
      if (named !== undefined) return named;
      const hex = /^&#x/i.test(entity), point = parseInt(entity.slice(hex ? 3 : 2), hex ? 16 : 10);
      return point <= 0x10ffff ? String.fromCodePoint(point) : '\ufffd';
    })
    .replace(/[\s\u200b\ufeff]/g, '');
}
function bodyCount(raw) { const text = bodyText(raw); return text === null ? null : [...text].length; }

// Bundled after the pure writing/count functions by build.cjs. No external imports.
(() => {
  'use strict';
  const doc = window.parent.document;
  const id = 'xzs-preset-controls-v01';
  // The iframe is unloaded by TavernHelper when this preset is deselected.
  if (doc.getElementById(id)) return;
  const root = doc.createElement('div'); root.id = id;
  const guardStyle = doc.createElement('style');
  guardStyle.textContent = '#chat .mes_reasoning_details{display:none!important} #chat .mes_text :is(think,thinking,reasoning,analysis,ecot,cot,draft,draft_notes,acg_think){display:none!important}';
  guardStyle.textContent += `
    #script_container_7b3378f3-7396-4b9c-a710-d50fbb98f160{min-width:0;max-width:100%}
    #script_container_7b3378f3-7396-4b9c-a710-d50fbb98f160 .qr--button.menu_button{box-sizing:border-box;min-height:44px;min-width:44px;width:max-content;max-width:100%;height:auto;padding:10px 12px;font-size:16px;line-height:1.4;display:inline-flex;align-items:center;justify-content:center;white-space:nowrap;flex:0 0 auto;touch-action:manipulation}
    #${id} *,#${id} dialog{box-sizing:border-box}
    #${id} form{display:flex;flex-direction:column;height:100%;min-height:0;margin:0;text-align:left}
    #${id} .xzs-heading{flex:none;padding:16px 18px 12px;border-bottom:1px solid #666}
    #${id} h3{margin:0;font-size:18px;line-height:1.4}
    #${id} .xzs-body{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;padding:14px 18px;display:flex;flex-direction:column;gap:12px;scroll-padding:12px}
    #${id} label{display:flex;flex-direction:column;gap:6px;min-width:0;flex:none}
    #${id} .xzs-range{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;flex:none}
    #${id} input,#${id} select,#${id} textarea{width:100%;max-width:100%;min-width:0;min-height:44px;margin:0;font:inherit;font-size:16px;line-height:1.4;padding:9px 10px}
    #${id} textarea{min-height:108px;resize:vertical}
    #${id} small{font-size:12px;line-height:1.5;overflow-wrap:anywhere;flex:none}
    #${id} output{font-size:13px;line-height:1.5;overflow-wrap:anywhere;flex:none}
    #${id} .xzs-footer{flex:none;padding:12px 18px calc(12px + env(safe-area-inset-bottom,0px));border-top:1px solid #666;display:flex;flex-direction:column;gap:8px;background:inherit}
    #${id} [name=status]{color:#f2cc8f}
    #${id} [name=status]:empty,#${id} [hidden]{display:none!important}
    #${id} .xzs-actions{display:flex;justify-content:flex-end;gap:12px}
    #${id} button{padding:9px 14px;border:1px solid #8993a5;border-radius:6px;background:#303747;color:#f4f6fb;cursor:pointer;font:inherit;font-size:16px;line-height:1.3;white-space:nowrap;width:auto;min-width:100px;max-width:none;min-height:44px;display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;touch-action:manipulation}
    #${id} button[type=submit]{background:#2d5b71}
    #${id} dialog[data-compact=true] .xzs-heading{padding:9px 14px}
    #${id} dialog[data-compact=true] .xzs-body{padding:10px 14px;gap:10px}
    #${id} dialog[data-compact=true] .xzs-footer{padding:8px 14px calc(8px + env(safe-area-inset-bottom,0px))}
    @media(max-width:600px){#${id} .xzs-heading{padding:12px 14px}#${id} .xzs-body{padding:12px 14px}#${id} .xzs-footer{padding:10px 14px calc(10px + env(safe-area-inset-bottom,0px))}#${id} .xzs-actions button{flex:1;min-width:0}}
  `;
  root.append(guardStyle);
  const panel = doc.createElement('dialog'); panel.setAttribute('aria-label','新中市预设设置');
  panel.style.cssText = 'position:fixed;inset:0 auto auto 0;margin:0;width:min(520px,calc(var(--xzs-viewport-width,100vw) - 24px));height:min(700px,calc(var(--xzs-viewport-height,100vh) - 24px - env(safe-area-inset-top,0px) - env(safe-area-inset-bottom,0px)));max-width:calc(100vw - 24px);overflow:hidden;padding:0;border:1px solid #777;border-radius:14px;background:var(--SmartThemeBlurTintColor,#252735);color:var(--SmartThemeBodyColor,#eee);font-family:inherit;font-size:14px;line-height:1.5';
  panel.innerHTML = `<form method="dialog">
    <header class="xzs-heading"><h3>新中市预设设置</h3></header>
    <div class="xzs-body">
      <label>正文字数<select name="length"><option value="short">短篇 · 400—700</option><option value="normal">常规 · 800—1400</option><option value="long">长篇 · 1600—2400</option><option value="custom">自定义上下限</option></select></label>
      <div class="xzs-range"><label>下限<input name="min" type="number" inputmode="numeric" min="100" max="10000" step="1"></label><label>上限<input name="max" type="number" inputmode="numeric" min="100" max="10000" step="1"></label></div>
      <small>按正文可见字符统计，标点、字母和数字各计一字；思考、时间戳、标签、协议和媒体不计。字数为写作目标，不会截断或自动重抽。</small>
      <label>文风<select name="style"></select></label>
      <label data-custom-style>自定义文风内容<textarea name="custom" rows="4" placeholder="填写希望单独使用的写作风格。"></textarea></label>
      <small>自定义文风与其他文风单选。切换后保留填写内容，只有选中时才生效。</small>
      <small>默认：第三人称 · 群像流动外部视角，不展示角色内心话。</small>
      <output name="count" aria-live="polite"></output>
    </div>
    <footer class="xzs-footer"><output name="status" aria-live="polite"></output><div class="xzs-actions"><button type="button" name="close">关闭</button><button type="submit">保存设置</button></div></footer>
  </form>`;
  root.append(panel);doc.body.append(root);
  const form = panel.querySelector('form'), field = name => form.elements.namedItem(name);
  const win=doc.defaultView,viewport=win.visualViewport,scrollBody=form.querySelector('.xzs-body');
  function place() {
    if(!panel.open)return;
    const height=viewport?.height||win.innerHeight,width=viewport?.width||win.innerWidth;
    panel.style.setProperty('--xzs-viewport-height',height+'px');panel.style.setProperty('--xzs-viewport-width',width+'px');
    panel.dataset.compact=String(height<480);
    panel.style.top=((viewport?.offsetTop||0)+Math.max(0,(height-panel.offsetHeight)/2))+'px';
    panel.style.left=((viewport?.offsetLeft||0)+Math.max(0,(width-panel.offsetWidth)/2))+'px';
  }
  function resize() { place();const active=doc.activeElement;if(panel.open&&scrollBody.contains(active))active.scrollIntoView({block:'nearest',inline:'nearest'}); }
  win.addEventListener('resize',resize);viewport?.addEventListener('resize',resize);viewport?.addEventListener('scroll',place);
  for (const [value,[label]] of Object.entries(styles)) { const option=doc.createElement('option');option.value=value;option.textContent=label;field('style').append(option); }
  function config() { try { return normalizeConfig(getVariables({type:'preset'}).xzsWriting || defaults); } catch { return {...defaults}; } }
  function setRange() {
    const mode=field('length').value, custom=mode==='custom';
    if (!custom) [field('min').value,field('max').value]=lengths[mode];
    field('min').disabled=field('max').disabled=!custom;
  }
  function setStyle() { const custom=field('style').value==='custom';field('custom').disabled=!custom;form.querySelector('[data-custom-style]').hidden=!custom; }
  function count() {
    const rows = window.parent.SillyTavern.getContext().chat || [];
    const row=rows.filter(m=>!m.is_user&&!m.is_system&&!m.is_hidden&&!m.hidden&&!m.is_archived&&!m.extra?.bbs_hidden).at(-1);
    const n=bodyCount(row?.mes),c=config();
    field('count').textContent=n===null?'当前回复没有 <content> 正文边界，暂不计数。':'当前有效回复正文：'+n+' 字'+(n<c.min?'（低于当前目标）':n>c.max?'（高于当前目标）':'（在当前目标内）');
  }
  function open() {
    const c=config();for(const key of ['length','min','max','style','custom'])field(key).value=c[key];
    setRange();setStyle();field('status').textContent='';count();if(!panel.open)panel.showModal();place();
  }
  field('close').addEventListener('click',()=>panel.close());
  field('length').addEventListener('change',setRange);
  field('style').addEventListener('change',setStyle);
  form.addEventListener('submit',event=>{
    event.preventDefault();
    try {
      const c=normalizeConfig(Object.fromEntries(['length','min','max','style','custom'].map(key=>[key,field(key).value])));
      const variables=getVariables({type:'preset'});variables.xzsWriting=c;replaceVariables(variables,{type:'preset'});
      field('status').textContent='已保存，从下一次生成生效。';count();
    } catch(error) { field('status').textContent=error.message; }
  });
  function prepare(payload) {
    const content=writingPrompt(config());
    for(const row of payload?.chat || []) {
      if(row.role==='assistant') {
        const delimiters=window.parent.SillyTavern.getContext().powerUserSettings?.reasoning;
        if(typeof row.content==='string')row.content=cleanOutput(row.content,delimiters);
        else if(Array.isArray(row.content))row.content=row.content.filter(part=>!['thinking','reasoning','redacted_thinking'].includes(part.type)).map(part=>part.type==='text'?{...part,text:cleanOutput(part.text,delimiters)}:part);
        for(const key of ['reasoning','reasoning_content','thinking','analysis'])delete row[key];
      }
      if(row.role!=='system')continue;
      if(typeof row.content==='string')row.content=row.content.replace(/<xzs_writing_config>[\s\S]*?<\/xzs_writing_config>/g,()=>content);
      else if(Array.isArray(row.content))for(const part of row.content)if(part.type==='text')part.text=part.text.replace(/<xzs_writing_config>[\s\S]*?<\/xzs_writing_config>/g,()=>content);
    }
  }
  eventOn(tavern_events.CHAT_COMPLETION_PROMPT_READY,prepare);
  eventOn(getButtonEvent('新中市预设设置'),open);
  for(const event of ['CHAT_CHANGED','MESSAGE_SWIPED','MESSAGE_EDITED','MESSAGE_UPDATED','MESSAGE_DELETED','MESSAGE_RECEIVED'])if(tavern_events[event])eventOn(tavern_events[event],()=>{if(panel.open)count();});
  window.addEventListener('pagehide',()=>{win.removeEventListener('resize',resize);viewport?.removeEventListener('resize',resize);viewport?.removeEventListener('scroll',place);panel.close();root.remove();},{once:true});
})();

// Preset-scoped routing. Read the same native World Info entries on every scan.
(() => {
  'use strict';
  const worldName = '新中市个人删减版（更新）';
  const routes = [18,20,1996,2071,2232,2234,2284,2285,2348,2467,2515,2635,3063,3672,3673,3674,3675,3676,3801,3802,3804,3805,3806,3807,3808,3813,3822,3823,3882,4135].map(uid => ({uid, promptId:'xzs-world-rule-'+uid, outlet:'XZS_RULE_'+uid}));
  function routeWorldRules(sources, preset) {
    const prompts = (preset?.prompts || []).filter(prompt => prompt.enabled);
    const active = new Map(routes.filter(route => {
      const macro = '{{outlet::'+route.outlet+'}}';
      const slot = prompts.find(prompt => prompt.id === route.promptId);
      return slot?.role === 'system' && slot.content?.includes(macro)
        && prompts.reduce((count,prompt) => count+String(prompt.content || '').split(macro).length-1,0) === 1;
    }).map(route => [route.uid,route]));
    let count = 0;
    for (const key of ['globalLore','characterLore','chatLore','personaLore']) {
      const entries = sources?.[key];
      if (!Array.isArray(entries)) continue;
      for (let index = 0; index < entries.length; index++) {
        const entry = entries[index], route = active.get(entry?.uid);
        if (!route || entry.world !== worldName || entry.disable) continue;
        // Only replace this scan's entry object. Never edit the World Info source.
        entries[index] = {...entry, position:7, outletName:route.outlet};
        count++;
      }
    }
    return count;
  }
  eventOn(tavern_events.WORLDINFO_ENTRIES_LOADED, sources => {
    if (window.parent.SillyTavern.getContext().mainApi !== 'openai') return;
    let preset;
    try { preset = getPreset('in_use'); } catch { return; }
    routeWorldRules(sources,preset);
  });
})();

// Lives inside this preset; never changes the player's saved connection or other presets.
(() => {
  'use strict';
  eventOn(tavern_events.CHAT_COMPLETION_SETTINGS_READY, data => {
    let preset;
    try{preset=getPreset('in_use');}catch{return;}
    if(!preset?.prompts?.some(p=>p.id==='xzs-camera'&&p.enabled))return;
    const model=String(data?.model||'').toLowerCase();
    const modernGemini=/^(?:google\/)?gemini-(?:3\.(?:[89])(?:[.-]|$)|4(?:[.-]|$))/.test(model);
    if(!modernGemini)return;
    for(const key of ['temperature','top_p','top_k','top_a','min_p','frequency_penalty','presence_penalty','repetition_penalty','n','candidate_count'])delete data[key];
    // Use the host's native reasoning field and keep reasoning out of the visible answer.
    data.include_reasoning=false;
    if(!data.reasoning_effort||['auto','minimal','min'].includes(data.reasoning_effort))data.reasoning_effort='medium';
    delete data.assistant_prefill;
  });
})();
